import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
      "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships"}

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb_root.find("m:sheets", NS)
    wb_rel = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {rel.attrib["Id"]: rel.attrib["Target"] for rel in wb_rel}
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss_root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss_root.findall("m:si", NS):
            shared.append("".join(t.text or "" for t in si.iter(f"{{{NS['m']}}}t")))
    print("shared strings:", shared)

    for s in sheets:
        name = s.attrib["name"]
        target = rels[s.attrib[f"{{{NS['r']}}}id"]]
        if not target.startswith("xl/"):
            target = "xl/" + target
        print(f"=== Sheet '{name}' -> {target} ===")
        ws_root = ET.fromstring(z.read(target))
        for row in ws_root.iter(f"{{{NS['m']}}}row"):
            cells = []
            for c in row.findall(f"{{{NS['m']}}}c"):
                ref = c.attrib.get("r")
                t = c.attrib.get("t")
                v = c.find(f"{{{NS['m']}}}v")
                val = None
                if v is not None:
                    if t == "s":
                        val = shared[int(v.text)]
                    elif t == "inlineStr":
                        is_el = c.find(f"{{{NS['m']}}}is")
                        val = "".join(tt.text or "" for tt in is_el.iter(f"{{{NS['m']}}}t"))
                    else:
                        val = v.text
                cells.append((ref, val))
            print("row", row.attrib.get("r"), cells)

